// Skip MRs already reviewed at their current head sha (workflow static data).
const store = $getWorkflowStaticData('global');
const reviewed = store.reviewed || {};
const out = [];
for (const item of $input.all()) {
  const mr = item.json;
  const key = String(mr.iid);
  if (reviewed[key] === mr.sha) continue;
  out.push({ json: mr });
}
return out;

const mr = $input.first().json;
const changes = mr.changes || [];
let diff = '';
for (const c of changes) {
  diff += 'diff --git a/' + (c.old_path || c.new_path) + ' b/' + c.new_path + '\n' + (c.diff || '') + '\n';
}
return [{ json: { iid: mr.iid, diff: diff.slice(0, 120000) } }];

// Record the reviewed head sha so the next run skips it.
const store = $getWorkflowStaticData('global');
store.reviewed = store.reviewed || {};
for (const item of $input.all()) {
  const mr = $('List open MRs').item.json;
  store.reviewed[String(mr.iid)] = mr.sha;
}
return $input.all();
